import type { PromptCategory } from "../../types/prompt";

export const businessPrompts: PromptCategory[] = [

    {
        id: "startup",
        name: "Startup & Entrepreneurship Prompts",
        icon: "🚀",
        description: "Free AI prompts for startups, entrepreneurs, and business founders",
        folders: [
            {
                id: "validation",
                name: "Idea Validation",
                icon: "✅",
                prompts: [
                    { id: "startup-validator", title: "Startup Idea Validator", content: "Validate startup idea for demand, feasibility, and risk. Idea: [DESCRIBE IDEA]. Validation framework: **1) Problem validation** - Is this a real, painful problem? Who has it? How do they solve it now? Will they pay for solution? **2) Market validation** - Market size (TAM/SAM/SOM), growth trends, competition analysis. **3) Solution validation** - Does your solution actually solve the problem? Is it 10x better than alternatives? **4) Founder-market fit** - Do you have domain expertise? Unique insights? Passion to persist? **5) Business model** - How will you make money? Unit economics, pricing strategy. **6) Risk assessment** - Technical risks, market risks, execution risks. Provide: validation score (1-10), key assumptions to test, recommended next steps (customer interviews, MVP, market research).", tags: ["Startup & Entrepreneurship", "Idea Validation"] },
                    { id: "market-demand", title: "Market Demand Analyzer", content: "Analyze whether a market is worth entering. Market: [DESCRIBE MARKET/NICHE]. Analysis framework: **1) Market size** - TAM (Total Addressable Market), SAM (Serviceable Available Market), SOM (Serviceable Obtainable Market). Use: industry reports, competitor revenue, Google Trends. **2) Growth rate** - Is market growing, stable, or declining? **3) Competition** - Who are the players? Market share distribution. Fragmented or dominated? **4) Customer pain** - How painful is the problem? Willingness to pay? **5) Barriers to entry** - Capital requirements, regulations, network effects, technology. **6) Trends** - Technology shifts, regulatory changes, consumer behavior. Verdict: Green light (large, growing, underserved), Yellow (proceed with caution), Red (avoid). Provide: data sources, key metrics, recommended positioning.", tags: ["Startup & Entrepreneurship", "Idea Validation"] },
                    { id: "competitive-analysis", title: "Competitive Analysis Generator", content: "Analyze competitors and identify positioning opportunities. Product: [YOUR PRODUCT]. Competitors: [LIST COMPETITORS]. Analysis framework: **1) Competitor mapping** - For each competitor: target customer, key features, pricing, strengths, weaknesses. **2) Feature comparison matrix** - Your product vs competitors across key features. **3) Positioning** - How do they position themselves? What's their unique value prop? **4) Gaps** - What are they missing? Underserved segments? **5) Differentiation** - How can you be different (better features, lower price, better UX, niche focus)? **6) Threats** - What could they do to compete with you? Create: competitive matrix, positioning map, differentiation strategy. Avoid: competing on features alone, ignoring indirect competitors.", tags: ["Startup & Entrepreneurship", "Idea Validation"] },
                    { id: "problem-solution-fit", title: "Problem-Solution Fit Checker", content: "Validate that your solution actually solves the problem. Problem: [DESCRIBE PROBLEM]. Solution: [YOUR SOLUTION]. Fit assessment: **1) Problem clarity** - Is the problem well-defined? Who experiences it? How often? **2) Current alternatives** - How do people solve this now? Why are alternatives insufficient? **3) Solution match** - Does your solution directly address the core problem? Or just symptoms? **4) User validation** - Have you talked to potential users? Do they agree this solves their problem? **5) Willingness to pay** - Would they pay for this? How much? **6) Adoption barriers** - What prevents them from using your solution? (learning curve, switching costs, integrations). Red flags: You're solving a problem you assume exists, solution is looking for a problem, users say 'nice to have' not 'must have'. Validation: 10+ customer interviews, prototype testing, pre-sales.", tags: ["Startup & Entrepreneurship", "Idea Validation"] },
                    { id: "feasibility-check", title: "Idea Feasibility Checker", content: "Evaluate technical and business feasibility of idea. Idea: [DESCRIBE]. Feasibility dimensions: **Technical feasibility** - Can this be built with current technology? Do you have the skills? Time estimate? Technical risks? **Financial feasibility** - Development costs, operating costs, runway needed, path to profitability. **Market feasibility** - Is there demand? Can you reach customers? Distribution channels? **Legal/regulatory** - Any compliance requirements? IP considerations? **Resource feasibility** - Do you have the team, time, money? What's missing? **Timeline feasibility** - Can you build and launch before market shifts or you run out of money? Scoring: Rate each dimension 1-10. Overall feasibility = average. <6 = high risk, 6-8 = proceed with caution, >8 = feasible. Provide: risk mitigation strategies, resource requirements, go/no-go recommendation.", tags: ["Startup & Entrepreneurship", "Idea Validation"] }
                ]
            },
            {
                id: "mvp-product",
                name: "MVP & Product Development",
                icon: "🛠️",
                prompts: [
                    { id: "mvp-scope", title: "MVP Scope Definer", content: "Define minimum viable product scope - what to build first. Product vision: [FULL VISION]. MVP definition: **1) Core value prop** - What's the ONE problem you're solving? **2) Must-have features** - Minimum features to deliver core value (typically 3-5 features). **3) Nice-to-have** - Features to add later. **4) Out of scope** - Features to explicitly exclude from MVP. **5) Success metrics** - How will you know if MVP works? (user retention, engagement, conversions). **6) Timeline** - How long to build MVP? (aim for 4-12 weeks). Example: For a task management app, MVP = create tasks, mark complete, basic lists. NOT in MVP = collaboration, integrations, mobile app, AI features. Principle: Build minimum to test core hypothesis. You can always add more. You can't get time back.", tags: ["Startup & Entrepreneurship", "MVP & Product Development"] },
                    { id: "feature-prioritization", title: "Feature Prioritization Matrix", content: "Prioritize features objectively using frameworks. Features to prioritize: [LIST FEATURES]. Prioritization methods: **1) RICE Score** - Reach (users affected) × Impact (1-3) × Confidence (%) / Effort (person-weeks). **2) MoSCoW** - Must have, Should have, Could have, Won't have. **3) Kano Model** - Basic (expected), Performance (more is better), Delight (unexpected wow). **4) Value vs Effort** - 2×2 matrix: High value + Low effort = Do first. High value + High effort = Plan carefully. Low value + Low effort = Maybe. Low value + High effort = Don't do. Create: Prioritized backlog, rationale for each decision, roadmap timeline. Consider: user impact, business value, technical dependencies, strategic importance. Review quarterly.", tags: ["Startup & Entrepreneurship", "MVP & Product Development"] },
                    { id: "mvp-roadmap", title: "MVP Roadmap Creator", content: "Create realistic MVP delivery roadmap. MVP scope: [FEATURES]. Team: [SIZE/SKILLS]. Timeline: [TARGET LAUNCH]. Roadmap structure: **Phase 1: Foundation (Week 1-2)** - Setup (repo, CI/CD, design system), core architecture, database schema. **Phase 2: Core Features (Week 3-6)** - Build must-have features, basic UI, authentication. **Phase 3: Integration (Week 7-8)** - Connect features, end-to-end flows, error handling. **Phase 4: Polish (Week 9-10)** - UX improvements, performance optimization, bug fixes. **Phase 5: Launch Prep (Week 11-12)** - Testing, documentation, deployment, monitoring setup. Include: milestones, dependencies, risks, buffer time (20%). Format: Gantt chart, sprint planning, weekly goals. Review: weekly progress, adjust timeline as needed.", tags: ["Startup & Entrepreneurship", "MVP & Product Development"] },
                    { id: "tech-feasibility", title: "Technical Feasibility Assessment", content: "Assess technical feasibility and choose tech stack. Product requirements: [DESCRIBE]. Assessment: **1) Technical challenges** - Identify hard problems (scale, real-time, AI/ML, security). **2) Tech stack options** - Evaluate frameworks, databases, infrastructure. **3) Scalability** - Can it handle growth? Bottlenecks? **4) Team expertise** - Does team know these technologies? Learning curve? **5) Development speed** - Time to MVP with each option? **6) Costs** - Infrastructure, licensing, third-party services. **7) Risks** - Technical debt, vendor lock-in, maintenance burden. Recommendation: Specific tech stack with justification. Example: 'React + Node.js + PostgreSQL + AWS because: team expertise, fast development, scalable, cost-effective for MVP.' Avoid: over-engineering, using new tech just to learn, ignoring team skills.", tags: ["Startup & Entrepreneurship", "MVP & Product Development"] },
                    { id: "mvp-launch", title: "MVP Launch Checklist", content: "Prepare for successful MVP launch. MVP: [PRODUCT]. Launch checklist: **Pre-launch:** ✓ Core features working, ✓ Critical bugs fixed, ✓ User testing completed, ✓ Analytics setup (Mixpanel/Amplitude), ✓ Error tracking (Sentry), ✓ Landing page live, ✓ Onboarding flow tested, ✓ Support channel ready, ✓ Pricing decided, ✓ Legal (terms, privacy policy). **Launch day:** ✓ Deploy to production, ✓ Smoke tests, ✓ Announce on social media, ✓ Email waitlist, ✓ Post on Product Hunt/HackerNews, ✓ Monitor errors and performance. **Post-launch (Week 1):** ✓ Collect user feedback, ✓ Fix critical bugs, ✓ Monitor key metrics, ✓ User interviews, ✓ Iterate quickly. Success metrics: signups, activation rate, retention, feedback quality. Goal: Learn fast, iterate fast.", tags: ["Startup & Entrepreneurship", "MVP & Product Development"] }
                ]
            },
            {
                id: "user-research",
                name: "User Research",
                icon: "👥",
                prompts: [
                    { id: "user-persona", title: "User Persona Generator", content: "Create realistic, research-based user personas. Product: [YOUR PRODUCT]. Persona framework: **Demographics** - Age, location, job title, income, education. **Psychographics** - Goals, motivations, values, frustrations. **Behaviors** - How they currently solve the problem, tools they use, decision-making process. **Pain points** - Specific problems they face, impact on their work/life. **Needs** - What they need from a solution, must-haves vs nice-to-haves. **Quote** - Fictional quote capturing their perspective. Create: 2-4 personas (primary, secondary). Example: 'Sarah, 32, Product Manager. Goal: Ship features faster. Frustration: Too many meetings, unclear priorities. Needs: Simple prioritization framework, stakeholder alignment. Quote: I spend more time in meetings than building product.' Base on: real user interviews, surveys, data, not assumptions.", tags: ["Startup & Entrepreneurship", "User Research"] },
                    { id: "pain-points", title: "User Pain Point Analyzer", content: "Identify and prioritize real user pain points. Users: [TARGET USERS]. Research methods: **1) User interviews** - Ask about their workflow, challenges, frustrations. 'Tell me about the last time you [did task].' **2) Surveys** - Quantify pain points, frequency, severity. **3) Analytics** - Where do users drop off? What features are unused? **4) Support tickets** - Common complaints, feature requests. **5) Competitor reviews** - What do users complain about? Pain point framework: **Frequency** - How often does this happen? **Severity** - How painful is it? (1-10). **Workarounds** - How do they solve it now? **Willingness to pay** - Would they pay to solve this? Prioritize: High frequency + High severity + No good workaround = Top priority. Create: Pain point map, prioritized list, opportunity areas.", tags: ["Startup & Entrepreneurship", "User Research"] },
                    { id: "customer-journey", title: "Customer Journey Mapper", content: "Map user journey from discovery to retention. Product: [YOUR PRODUCT]. Journey stages: **1) Awareness** - How do they discover you? (search, referral, ads). Touchpoints: landing page, social media, content. **2) Consideration** - How do they evaluate you? Touchpoints: product page, pricing, testimonials, competitor comparison. **3) Acquisition** - How do they sign up? Touchpoints: signup flow, onboarding, first-time experience. **4) Activation** - When do they get value? Touchpoints: aha moment, core feature usage. **5) Retention** - Why do they come back? Touchpoints: email, notifications, new features. **6) Referral** - Why do they recommend you? Touchpoints: referral program, social sharing. For each stage: User actions, thoughts/emotions, pain points, opportunities. Identify: drop-off points, friction, moments of delight. Optimize: conversion at each stage.", tags: ["Startup & Entrepreneurship", "User Research"] },
                    { id: "user-interview-questions", title: "User Interview Question Generator", content: "Generate effective user interview questions. Research goal: [WHAT YOU WANT TO LEARN]. Question types: **Background** - 'Tell me about your role', 'Walk me through a typical day'. **Current behavior** - 'How do you currently [do task]?', 'What tools do you use?'. **Pain points** - 'What's frustrating about [process]?', 'What takes the most time?'. **Needs** - 'What would make this easier?', 'If you had a magic wand...'. **Past experiences** - 'Tell me about the last time you [did task]', 'What went wrong?'. **Solution validation** - 'How would you feel if you could [feature]?', 'Would you pay for this?'. Best practices: Open-ended questions, ask 'why' 5 times, listen more than talk, avoid leading questions, focus on past behavior not hypotheticals. Interview length: 30-45 minutes. Number: 10-15 interviews for patterns.", tags: ["Startup & Entrepreneurship", "User Research"] },
                    { id: "persona-validation", title: "Persona Validation Checklist", content: "Validate assumptions about your users with real data. Personas: [YOUR PERSONAS]. Validation methods: **1) Quantitative validation** - Survey 50+ users, analyze demographics, behaviors, tool usage. Do they match personas? **2) Qualitative validation** - Interview 10-15 users, ask about goals, pain points, workflows. Do quotes match persona quotes? **3) Behavioral validation** - Analyze product analytics, feature usage, user flows. Do behaviors match persona behaviors? **4) Segment analysis** - Can you identify distinct user segments in data? Do they align with personas? Red flags: Personas based on assumptions not research, too many personas (>5), personas that all look the same, no data to support. Update: Quarterly based on new research, user feedback, product analytics. Personas should evolve as you learn.", tags: ["Startup & Entrepreneurship", "User Research"] }
                ]
            },
            {
                id: "fundraising",
                name: "Fundraising & Pitch",
                icon: "💰",
                prompts: [
                    { id: "pitch-deck", title: "Pitch Deck Improver", content: "Improve pitch deck for investor presentations. Current deck: [DESCRIBE/ATTACH]. Pitch deck structure (10-15 slides): **1) Cover** - Company name, tagline, your name. **2) Problem** - What problem are you solving? Make it relatable. **3) Solution** - Your product. Show, don't just tell. **4) Market opportunity** - TAM/SAM/SOM, market trends. **5) Product** - Demo or screenshots, key features. **6) Traction** - Users, revenue, growth rate, key metrics. **7) Business model** - How you make money, unit economics. **8) Competition** - Competitive landscape, your differentiation. **9) Go-to-market** - Customer acquisition strategy, channels. **10) Team** - Founders, key hires, advisors, why you're uniquely qualified. **11) Financials** - Revenue projections, burn rate, runway. **12) Ask** - How much you're raising, what you'll use it for. Design: Clean, visual, minimal text, consistent branding. Tell a story.", tags: ["Startup & Entrepreneurship", "Fundraising & Pitch"] },
                    { id: "investor-storytelling", title: "Investor Storytelling Assistant", content: "Craft compelling narrative for investors. Company: [YOUR STARTUP]. Story structure: **1) The hook** - Start with surprising insight or personal story. 'Did you know [stat]?' or 'Three years ago, I experienced [problem]...' **2) The problem** - Paint vivid picture of the pain. Make it personal and relatable. **3) The aha moment** - When did you realize this was a big opportunity? **4) The solution** - Your unique insight. Why now? Why you? **5) The vision** - Where is this going? What's the big opportunity? **6) The proof** - Traction, validation, why it's working. **7) The ask** - What you need to get there. Storytelling principles: Concrete examples over abstract concepts, show don't tell, make it personal, create emotional connection, build tension and resolution. Practice: 2-minute elevator pitch, 10-minute meeting pitch, 30-minute deep dive.", tags: ["Startup & Entrepreneurship", "Fundraising & Pitch"] },
                    { id: "problem-solution-narrative", title: "Problem-Solution Narrative Builder", content: "Clearly articulate problem and solution for investors. Problem: [DESCRIBE]. Solution: [YOUR PRODUCT]. Narrative framework: **Problem statement:** '[TARGET USER] struggles with [SPECIFIC PROBLEM] which causes [NEGATIVE IMPACT]. Current solutions [ALTERNATIVES] are insufficient because [WHY THEY FAIL]. This affects [MARKET SIZE] people/companies, costing them [TIME/MONEY].' **Solution statement:** '[YOUR PRODUCT] solves this by [HOW IT WORKS]. Unlike [ALTERNATIVES], we [UNIQUE APPROACH]. This enables users to [BENEFIT], saving them [QUANTIFIED VALUE].' **Proof:** 'We've validated this with [TRACTION/DATA]. Users tell us [QUOTE]. Our [METRIC] is growing [GROWTH RATE].' Make it: Specific (numbers, names), relatable (investors can understand the pain), credible (backed by data), compelling (big opportunity).", tags: ["Startup & Entrepreneurship", "Fundraising & Pitch"] },
                    { id: "market-sizing", title: "Market Sizing Explainer", content: "Explain TAM, SAM, and SOM clearly with defensible numbers. Product: [YOUR PRODUCT]. Market sizing: **TAM (Total Addressable Market)** - If you had 100% market share with no constraints. Calculation: Total potential users × Average revenue per user. Example: '500M small businesses globally × $1000/year = $500B TAM'. **SAM (Serviceable Available Market)** - Portion of TAM you can reach with your current product/business model. Example: 'English-speaking countries, B2B SaaS only = $50B SAM'. **SOM (Serviceable Obtainable Market)** - Realistic market share you can capture in 3-5 years. Example: 'Capturing 1% of SAM = $500M SOM'. Data sources: Industry reports (Gartner, Forrester), competitor revenue, census data, surveys. Bottom-up validation: 'We have 1000 customers paying $1000/year = $1M ARR. There are 50,000 similar companies = $50M realistic market.' Investors want: Large TAM (>$1B), growing market, bottom-up validation.", tags: ["Startup & Entrepreneurship", "Fundraising & Pitch"] },
                    { id: "funding-readiness", title: "Funding Readiness Checker", content: "Assess if you're ready to raise funding. Stage: [PRE-SEED/SEED/SERIES A]. Readiness checklist: **Product** - ✓ MVP built and working, ✓ Users are using it, ✓ Core features validated. **Traction** - ✓ User growth, ✓ Revenue (if applicable), ✓ Engagement metrics, ✓ Testimonials/case studies. **Team** - ✓ Founders committed full-time, ✓ Complementary skills, ✓ Relevant experience, ✓ Advisors. **Market** - ✓ Large addressable market, ✓ Clear target customer, ✓ Competitive differentiation. **Financials** - ✓ Financial model, ✓ Unit economics, ✓ Use of funds plan, ✓ 18-month runway post-raise. **Materials** - ✓ Pitch deck, ✓ Executive summary, ✓ Financial projections, ✓ Data room. Red flags: No traction, unclear business model, team conflicts, no clear use of funds. Typical traction: Pre-seed (idea + prototype), Seed (10K+ users or $10K+ MRR), Series A ($100K+ MRR, clear PMF).", tags: ["Startup & Entrepreneurship", "Fundraising & Pitch"] }
                ]
            },
            {
                id: "gtm",
                name: "Go-To-Market",
                icon: "📈",
                prompts: [
                    { id: "gtm-strategy", title: "Go-To-Market Strategy Builder", content: "Plan how to acquire first 100, 1000, 10000 customers. Product: [YOUR PRODUCT]. Target: [CUSTOMER SEGMENT]. GTM strategy: **1) Customer acquisition channels** - Where does your target customer hang out? (LinkedIn, Twitter, Reddit, communities, conferences). **2) Channel strategy** - First 100: Do things that don't scale (manual outreach, founder-led sales, content, communities). First 1000: Scale what worked (paid ads, partnerships, content marketing, SEO). First 10000: Optimize and diversify (multiple channels, automation, sales team). **3) Messaging** - What's your value prop? How do you explain it? **4) Pricing** - Freemium, free trial, or paid from day 1? **5) Onboarding** - How do you activate users? **6) Metrics** - CAC, LTV, conversion rates, retention. Example: B2B SaaS: First 100 via LinkedIn outreach + content. First 1000 via SEO + partnerships. First 10000 via paid ads + sales team.", tags: ["Startup & Entrepreneurship", "Go-To-Market"] },
                    { id: "user-acquisition", title: "User Acquisition Strategy Planner", content: "Plan systematic user acquisition across channels. Product: [DESCRIBE]. Budget: [AMOUNT]. Acquisition channels: **Organic** - SEO (blog content, keywords), Social media (LinkedIn, Twitter), Communities (Reddit, Discord, Slack groups), PR/Media, Referrals. **Paid** - Google Ads, Facebook/Instagram Ads, LinkedIn Ads, Sponsorships, Influencers. **Partnerships** - Integration partners, Affiliate programs, Co-marketing. **Sales** - Outbound (cold email, LinkedIn), Inbound (demos, trials). For each channel: Target audience, Expected CAC, Expected volume, Timeline to results, Resources needed. Start with: 2-3 channels, test, measure, double down on what works. Metrics: CAC, LTV, CAC payback period, channel ROI. Goal: CAC < LTV/3, multiple acquisition channels.", tags: ["Startup & Entrepreneurship", "Go-To-Market"] },
                    { id: "messaging-positioning", title: "Messaging & Positioning Assistant", content: "Define clear, compelling messaging and positioning. Product: [YOUR PRODUCT]. Positioning framework: **1) Target customer** - Who is this for? Be specific. **2) Problem** - What problem do they have? **3) Category** - What category do you compete in? (or create new category). **4) Unique value** - Why are you different/better? **5) Proof** - Why should they believe you? April Dunford framework: 'For [TARGET CUSTOMER] who [PROBLEM], [PRODUCT] is a [CATEGORY] that [UNIQUE VALUE]. Unlike [ALTERNATIVES], we [DIFFERENTIATION].' Example: 'For busy developers who struggle with API documentation, ReadMe is a documentation platform that keeps docs always up-to-date. Unlike static docs, we integrate with your codebase and auto-update.' Test: Does target customer immediately understand? Do they care? Is it differentiated? Avoid: jargon, being everything to everyone, feature lists without benefits.", tags: ["Startup & Entrepreneurship", "Go-To-Market"] },
                    { id: "cac-optimizer", title: "Customer Acquisition Cost Optimizer", content: "Optimize CAC across channels. Current CAC: [AMOUNT]. Optimization tactics: **1) Funnel analysis** - Where are users dropping off? Improve conversion at weakest point = lower CAC. **2) Creative testing** - Test 10+ ad variations. CTR increase from 1% to 2% halves CPC. **3) Audience refinement** - Exclude low-converting segments, lookalike audiences based on high-LTV users. **4) Retargeting** - Cheaper to convert warm leads than cold. **5) Organic lift** - Improve SEO/referrals to lower blended CAC. **6) Landing page CRO** - Match ad message to landing page headline. Goal: LTV:CAC ratio > 3:1.", tags: ["Startup & Entrepreneurship", "Go-To-Market"] },
                    { id: "growth-experiments", title: "Growth Hacking Experiments Framework", content: "Systematize growth experiments. Goal: [METRIC TO IMPROVE]. Experiment framework (ICE Score): **Idea** - [HYPOTHESIS]. **Impact** (1-10) - How big of a difference will this make? **Confidence** (1-10) - How sure are we it will work? **Ease** (1-10) - How easy is it to implement? Prioritize high ICE score. **Design**: Control vs Variant. **Metric**: What defines success? **Duration**: How long to run? **Result**: Win/Fail/Inconclusive. **Action**: Implement/Discard/Iterate. Example: 'Idea: Add social proof to signup page. Hypothesis: Conversion increases 10%. Test: A/B test for 2 weeks.'", tags: ["Startup & Entrepreneurship", "Go-To-Market"] },
                    { id: "market-expansion", title: "Market Expansion Strategy", content: "Evaluate and plan market expansion. Current market: [CURRENT]. Expansion options: **1) Geographic** - New city, country, region. Requires localization, legal compliance. **2) Demographic** - New user segment (e.g., Enterprise vs SMB). Requires feature changes, sales motion. **3) Channel** - New distribution (e.g., Retail vs D2C). **4) Product** - New product line for same customers. Evaluation: Market size, Competition, Strategic fit, Cost to enter. Strategy: Pilot first -> Measure traction -> Scale. Risk: Diluting focus, running out of cash.", tags: ["Startup & Entrepreneurship", "Go-To-Market"] }
                ]
            }
        ]
    },
    {
        id: "strategy-finance-ops",
        name: "Strategy, Finance & Operations",
        icon: "💼",
        description: "Business planning, financial management, operations, and legal frameworks",
        folders: [
            {
                id: "business-planning",
                name: "Business Planning & Models",
                icon: "📊",
                prompts: [
                    { id: "business-plan-template", title: "Comprehensive Business Plan", content: "Create a detailed business plan structure. Business: [BUSINESS TYPE/IDEA]. Structure: **Executive Summary** - Vision, mission, objectives. **Company Overview** - Structure, ownership, history. **Products/Services** - Detailed description, USP, lifecycle. **Market Analysis** - Industry analysis, target market, competition. **Marketing Strategy** - Pricing, distribution, promotion. **Operational Plan** - Location, equipment, personnel, processes. **Management Team** - Org chart, key roles. **Financial Plan** - Assumptions, forecasts, funding requirements. Critical: Focus on viability and scalability.", tags: ["Strategy, Finance & Operations", "Business Planning"] },
                    { id: "lean-canvas", title: "Lean Canvas Creator", content: "Generate a Lean Canvas for rapid business modeling. Idea: [IDEA]. Sections: **1) Problem** - Top 3 problems. **2) Customer Segments** - Target customers/users. **3) Unique Value Proposition** - Single clear compelling message. **4) Solution** - Top 3 features. **5) Channels** - Path to customers. **6) Revenue Streams** - Revenue model, life time value, gross margin. **7) Cost Structure** - Customer acquisition costs, distribution costs, hosting, people. **8) Key Metrics** - Key activities you measure. **9) Unfair Advantage** - Can't be easily copied or bought. Purpose: Validate business model before building.", tags: ["Strategy, Finance & Operations", "Business Planning"] },
                    { id: "business-model-canvas", title: "Business Model Canvas", content: "Fill out Business Model Canvas (BMC). Business: [BUSINESS]. Components: **Key Partners** - Suppliers, partners. **Key Activities** - What do you do? **Key Resources** - Assets required. **Value Propositions** - What value do you deliver? **Customer Relationships** - Type of relationship (personal, automated). **Channels** - How do you reach them? **Customer Segments** - Who are you creating value for? **Cost Structure** - Most important costs. **Revenue Streams** - How do you make money? Use: Strategic management and entrepreneurial tool.", tags: ["Strategy, Finance & Operations", "Business Planning"] },
                    { id: "value-prop-design", title: "Value Proposition Designer", content: "Design a compelling Value Proposition. Product: [PRODUCT] for [CUSTOMER]. Canvas: **Customer Profile**: Gains (outcomes they want), Pains (bad outcomes/risks), Customer Jobs (what they are trying to do). **Value Map**: Gain Creators (how you create benefits), Pain Relievers (how you resolve pains), Products & Services (what you offer). Fit: Ensure distinct match between Pains/Pain Relievers and Gains/Gain Creators. Statement: 'Our [product] helps [segment] who want to [job] by [verb] [benefit] and [verb] [pain].'", tags: ["Strategy, Finance & Operations", "Business Planning"] },
                    { id: "swot-analysis", title: "SWOT Analysis Framework", content: "Conduct detailed SWOT analysis. Subject: [COMPANY/STRATEGY]. Grid: **Strengths** (Internal/Positive) - Capabilities, resources, assets, people. **Weaknesses** (Internal/Negative) - Gaps, lack of resources, processes. **Opportunities** (External/Positive) - Market trends, tech changes, competitor errors. **Threats** (External/Negative) - Competitors, economy, regulations. Strategy generation: SO (Use strengths to maximize opportunities), WO (Improve weaknesses using opportunities), ST (Use strengths to minimize threats), WT (Minimize weaknesses to avoid threats).", tags: ["Strategy, Finance & Operations", "Business Planning"] },
                    { id: "market-entry", title: "Market Entry Strategy", content: "Plan strategy for entering new market. Target: [MARKET/REGION]. Components: **Market Assessment** - Size, growth, trends. **Entry Mode** - Export, licensing, franchising, joint venture, wholly owned subsidiary. **Timing** - First mover vs fast follower. **Marketing Mix** - Product adaptation, pricing strategy, distribution channels, promotion. **Risk Analysis** - Political, economic, legal, cultural risks. **Implementation Plan** - 30/60/90 day roadmap. Goal: Minimize risk while maximizing speed to market.", tags: ["Strategy, Finance & Operations", "Business Planning"] },
                    { id: "competitive-advantage", title: "Competitive Advantage Identifier", content: "Identify and strengthen sustainable competitive advantage. Business: [BUSINESS]. Sources of advantage: **Cost Leadership** (lowest cost producer), **Differentiation** (unique features/brand), **Focus** (niche specialization). Analysis: VRIO Framework - Is the resource/capability **Valuable**? **Rare**? **Inimitable** (hard to copy)? **Organized** to capture value? Strategy: strengthening the moat (IP, network effects, brand, switching costs, economies of scale).", tags: ["Strategy, Finance & Operations", "Business Planning"] },
                    { id: "blue-ocean", title: "Blue Ocean Strategy Canvas", content: "Create Blue Ocean Strategy to make competition irrelevant. Industry: [INDUSTRY]. Four Actions Framework: **Eliminate** - Which factors that industry takes for granted should be eliminated? **Reduce** - Which factors should be reduced well below industry standard? **Raise** - Which factors should be raised well above industry standard? **Create** - Which factors should be created that industry has never offered? Goal: Value Innovation (lower cost + higher value). Output: New Strategy Canvas curve.", tags: ["Strategy, Finance & Operations", "Business Planning"] },
                    { id: "business-case", title: "Business Case Builder", content: "Build comprehensive business case for investment/project. Project: [PROJECT]. Structure: **Executive Summary**. **Problem Statement** - Why change? **Strategic Alignment** - How it fights goals. **Options Analysis** - Do nothing vs Option A vs Option B. **Cost-Benefit Analysis** - Financial (ROI, NPV, Payback) and Non-financial benefits. **Risks** - Key risks and mitigation. **Recommendation** - Preferred option. **Implementation Plan** - Timeline and resources. Purpose: Justify allocation of resources.", tags: ["Strategy, Finance & Operations", "Business Planning"] },
                    { id: "strategic-planning", title: "Strategic Planning Framework", content: "Facilitate strategic planning process. Timeframe: [3-5 YEARS]. Steps: **1) Vision/Mission/Values** - Where are we going? **2) Current State Analysis** - SWOT, PESTLE. **3) Strategic Objectives** - High-level goals (Financial, Customer, Internal, Learning). **4) Strategy Map** - Cause-and-effect measure. **5) KPIs & Targets** - Measuring success. **6) Strategic Initiatives** - Projects to achieve targets. **7) Execution** - Cascading goals, monitoring logic. Outcome: Clear roadmap from vision to execution.", tags: ["Strategy, Finance & Operations", "Business Planning"] },
                    { id: "scenario-planning", title: "Scenario Planning Tool", content: "Develop scenarios for future uncertainty. Topic: [Topic/Industry]. Process: **1) Identify Driving Forces** - Trends, uncertainties (e.g., AI regulation, economic downturn). **2) Identify Critical Uncertainties** - Top 2 most impactful/uncertain forces. **3) Create Matrix** - 2x2 grid of uncertainties. **4) Develop Scenarios** - Narratives for each quadrant (Best case, Worst case, etc.). **5) Implications** - What happens to our business in each? **6) Early Warning Signals** - Indicators that a scenario is unfolding. **7) Strategy** - Robust strategies that work in multiple scenarios.", tags: ["Strategy, Finance & Operations", "Business Planning"] },
                    { id: "risk-matrix", title: "Risk Assessment Matrix", content: "Create Risk Assessment Matrix. Context: [PROJECT/BUSINESS]. Matrix: **Likelihood** (Rare, Unlikely, Possible, Likely, Almost Certain) vs **Impact** (Insignificant, Minor, Moderate, Major, Severe). Action: **Low Risk** (Accept/Monitor), **Medium Risk** (Mitigate/Manage), **High Risk** (Avoid/Transfer/Mitigate aggressively). For each risk: Identify -> Analyze -> Evaluate -> Treat. Treatments: Avoid (stop activity), Reduce (controls), Share (insurance/outsource), Accept (budget for it).", tags: ["Strategy, Finance & Operations", "Business Planning"] }
                ]
            },
            {
                id: "pricing-strategy-models",
                name: "Pricing Strategy & Models",
                icon: "💰",
                prompts: [
                    { id: "b2b-marketplace-pricing", title: "B2B Marketplace Pricing", content: "Develop a comprehensive pricing strategy for a B2B marketplace connecting [suppliers] and [buyers]. Analyze different revenue models (commission, subscription, listing fees, lead fees) and recommend the optimal mix for early-stage growth versus long-term profitability. Address dynamic pricing mechanisms, tiered service levels for power users, and strategies to prevent platform leakage (disintermediation).", tags: ["Business Strategy & Pricing", "Pricing Strategy & Models"] },
                    { id: "industry-saas-pricing", title: "Industry-Specific SaaS Pricing", content: "Create a tailored pricing model for a SaaS platform serving the [specific industry, e.g., construction, healthcare] sector. Consider industry-specific budget cycles, procurement processes, and key value metrics (e.g., number of projects, patient volume). Propose three pricing tiers (Starter, Professional, Enterprise) with feature differentiators that align with customer growth stages in this specific vertical.", tags: ["Business Strategy & Pricing", "Pricing Strategy & Models"] },
                    { id: "ecommerce-pricing", title: "E-commerce Dynamic Pricing", content: "Design a dynamic pricing algorithm framwork for an e-commerce store selling [product category]. Outline variables to consider (competitor prices, demand fluctuations, inventory levels, time of day, customer segment). Propose rules for automated price adjustments to maximize margins without eroding brand trust. Include strategies for psychological pricing and promotional discounting.", tags: ["Business Strategy & Pricing", "Pricing Strategy & Models"] },
                    { id: "subscription-saas-pricing", title: "Subscription-Based SaaS Pricing", content: "Structure a subscription pricing model for a [product type] SaaS tool. Define value metrics (per user, per seat, usage-based, flat rate) and justify the choice based on customer value alignment. Create detailed descriptions for 'Freemium', 'Pro', and 'Business' plans, highlighting the features that drive upgrades/upsells at each level. Include a strategy for annual vs. monthly billing incentives.", tags: ["Business Strategy & Pricing", "Pricing Strategy & Models"] },
                    { id: "enterprise-saas-pricing", title: "Enterprise SaaS Pricing", content: "Formulate an enterprise pricing strategy for large organizations using [software type]. Focus on custom quoting, volume discounts, SLA (Service Level Agreement) premiums, and dedicated support costs. Structure a 'Call for Pricing' tier that accounts for complex implementations, security compliance needs (SSO, SOC2), and account management. detailed negotiation levers for sales teams.", tags: ["Business Strategy & Pricing", "Pricing Strategy & Models"] },
                    { id: "pricing-analysis", title: "Comprehensive Pricing Analysis", content: "Conduct a pricing audit for [company/product]. Analyze current pricing against top 3 competitors. Identify gaps in value capture (underpricing) or barriers to entry (overpricing). Evaluate the effectiveness of current packaging and bundling. Recommend specific price point adjustments and A/B testing experiments to optimize conversion rates and average revenue per user (ARPU).", tags: ["Business Strategy & Pricing", "Pricing Strategy & Models"] }
                ]
            },
            {
                id: "financial-management",
                name: "Financial Management & Metrics",
                icon: "💹",
                prompts: [
                    { id: "financial-projection", title: "Financial Projection Model", content: "Create 3-year financial projection. Business: [TYPE]. Inputs: [ASSUMPTIONS]. Model structure: **Revenue** - Monthly Recurring Revenue (MRR), One-time sales. **COGS** - Hosting, support, licenses. **Gross Margin** - Revenue minus COGS. **OpEx** - Sales & Marketing, R&D, G&A (Salaries, Rent, Software). **EBITDA** - Earnings Before Interest, Taxes, Depreciation, Amortization. **Net Income**. Output: Monthly and annual view. Purpose: Planning, fundraising, cash flow management.", tags: ["Strategy, Finance & Operations", "Financial Management"] },
                    { id: "cash-flow-forecast", title: "Cash Flow Forecasting", content: "Forecast 13-week cash flow. Current bank balance: [AMOUNT]. Inputs: **Inflows** - Customer payments (timing), Investment. **Outflows** - Payroll (bi-weekly), Rent (monthly), Software subs, Vendor payments. **Net Burn** - Outflows minus Inflows. **Runway** - Months of cash left. Warning signals: <3 months runway, large one-time payments. Goal: Never run out of cash. Monitor weekly.", tags: ["Strategy, Finance & Operations", "Financial Management"] },
                    { id: "break-even-analysis", title: "Break-Even Analysis", content: "Calculate break-even point. inputs: **Fixed Costs** - Rent, salaries, software (e.g., $10k/mo). **Variable Costs** - Payment processing, COGS per unit (e.g., $50/unit). **Price** - Revenue per unit (e.g., $100/unit). **Contribution Margin** - Price - Variable Cost ($50). **Break-Even Point** - Fixed Costs / Contribution Margin ($10k / $50 = 200 units). Interpretation: You must sell 200 units/mo to cover costs. Anything above is profit.", tags: ["Strategy, Finance & Operations", "Financial Management"] },
                    { id: "unit-economics", title: "Unit Economics Calculator", content: "Analyze unit economics. Unit: [CUSTOMER/TRANSACTION]. Metrics: **LTV (Lifetime Value)** - ARPU x Gross Margin % / Churn Rate. **CAC (Customer Acquisition Cost)** - Marketing Spend / New Customers. **LTV:CAC Ratio** - Ideal > 3:1. **Payback Period** - Months to recover CAC. **Gross Margin** - Revenue - Direct Costs. **Churn** - % customers lost monthly. Analysis: Positive unit economics means you lose money on every sale? Fix pricing or costs. Negative unit economics? Do not scale yet.", tags: ["Strategy, Finance & Operations", "Financial Management"] },
                    { id: "pl-statement", title: "P&L Statement Builder", content: "Generate P&L (Profit & Loss) structure. Business: [TYPE]. Categories: **Revenue** (Sales, Services). **Direct Costs** (Materials, Labor). **Gross Profit**. **Operating Expenses**: Salaries & Wages, Rent & Utilities, Marketing & Advertising, Software & Tools, Professional Services (Legal/Accounting), Travel & Meals, Insurance. **Operating Income**. **Other Income/Expense** (Interest, Tax). **Net Profit**. Review monthly to track profitability.", tags: ["Strategy, Finance & Operations", "Financial Management"] },
                    { id: "budget-planning", title: "Annual Budget Planning Template", content: "Create annual budget plan. Year: [YEAR]. Department breakdown: **Engineering** - Headcount, AWS, Tools. **Sales** - Headcount, Commission, Travel, CRM. **Marketing** - Ad spend, Agency fees, Events. **Product** - Analytics, Design tools. **G&A** - Rent, Legal, Admin, Finance. Process: 1) Set revenue target. 2) Determine target margin. 3) Allocate OpEx budget to depts. 4) Department leads detailed line items. 5) Review and approve. Track actual vs budget monthly.", tags: ["Strategy, Finance & Operations", "Financial Management"] },
                    { id: "runway-calculator", title: "Startup Runway Calculator", content: "Calculate and extend runway. Cash in bank: [AMOUNT]. Monthly burn rate: [AMOUNT]. **Current Runway** = Cash / Burn = [MONTHS]. Extension strategies: **Revenue** - Increase prices, annual prepayments. **Cost Cutting** - Freeze hiring, cut marketing, renegotiate contracts, reduce SaaS spend. **Fundraising** - Start 6 months before zero date. Goal: maintain 18+ months runway for stability.", tags: ["Strategy, Finance & Operations", "Financial Management"] },
                    { id: "kpi-dashboard", title: "KPI Dashboard Creator", content: "Design executive KPI dashboard. Industry: [INDUSTRY]. Sections: **Financial** - MRR/ARR, Burn Rate, Cash Balance, Gross Margin. **Customer** - New Logos, Churn Rate, NPS, Active Users (DAU/MAU). **Sales** - Pipeline Value, Win Rate, CAC, Sales Cycle Length. **Operational** - Server Uptime, Support Ticket Volume, Bug Count. Frequency: Weekly review. Owner: CEO/CFO/COO.", tags: ["Strategy, Finance & Operations", "Financial Management"] },
                    { id: "financial-health", title: "Financial Health Scorecard", content: "Assess business financial health. Scorecard: **Liquidity** - Current Ratio (Assets/Liabilities > 1.5). **Solvency** - Debt-to-Equity. **Profitability** - Net Margin (Industry avg). **Efficiency** - Asset Turnover. **Growth** - YoY Revenue Growth. Rating (1-5) for each. Action: Focus on lowest score. Example: Low liquidity -> Improve collections, reduce inventory.", tags: ["Strategy, Finance & Operations", "Financial Management"] },
                    { id: "cost-structure", title: "Cost Structure Optimizer", content: "Identify and optimize cost drivers. Top expenses: [LIST]. Optimization: **Fixed vs Variable** - Can you turn fixed costs (salaries) into variable (contractors)? **Vendor negotiation** - Ask for discounts on renewals. **Waste** - Unused software seats, unnecessary features. **Scale economies** - Bulk purchasing. **Process efficiency** - Automate manual tasks to save labor. Goal: Leaner cost structure improves margins and survival.", tags: ["Strategy, Finance & Operations", "Financial Management"] },
                    { id: "roi-calculator", title: "ROI Calculator", content: "Calculate ROI for investment decision. Project: [PROJECT - e.g., New Marketing Channel]. **Cost**: Setup + Ad Spend + Labor ($10k). **Return**: Expected Revenue - Direct Costs ($30k). **ROI** = (Return - Cost) / Cost x 100%. ($20k / $10k = 200%). **Timeframe**: When is return realized? **Risk Adjustment**: Discount return by probability of success (e.g., 70%). Decision rule: ROI > Hurdle Rate (e.g., 15%).", tags: ["Strategy, Finance & Operations", "Financial Management"] },
                    { id: "pricing-psychology", title: "Pricing Psychology Framework", content: "Apply psychology to pricing strategy. Product: [PRODUCT]. Tactics: **Anchoring** - Show expensive option first. **Decoy Effect** - Add 3rd option to make middle option look best. **Ending in 9** - $99 vs $100. **Bundling** - Reduce pain of paying by combining items. **Price vs Value** - Reframe price (e.g., 'cost of a coffee per day'). **Trial** - Reduce risk with money-back guarantee. **Scarcity** - Limited time offers. Goal: Maximize perceived value and conversion.", tags: ["Strategy, Finance & Operations", "Financial Management"] }
                ]
            },
            {
                id: "operations-optimization",
                name: "Operations & Optimization",
                icon: "⚙️",
                prompts: [
                    { id: "sop-template", title: "Standard Operating Procedure (SOP) Template", content: "Create SOP for recurring task. Task: [TASK NAME]. Header: Title, Owner, Date, Version. **Purpose** - Why do this? **Scope** - When applies? **Prerequisites** - Tools/access needed. **Procedure** - Step-by-step instructions (numbered). Use screenshots/videos. **Troubleshooting** - Common issues. **Success Criteria** - Definition of done. Benefit: Consistency, scalability, easy delegation.", tags: ["Strategy, Finance & Operations", "Operations"] },
                    { id: "process-mapping", title: "Process Mapping Tool", content: "Map existing business process. Process: [PROCESS Name]. Steps: **Start** - Trigger event. **Inputs** - Information/materials needed. **Steps** - Sequential actions (Who does what?). **Decision Points** - Yes/No branches. **Outputs** - Result of process. **End** - Completion. Identify: Bottlenecks (where it slows), Redundancy (duplicate work), Handoffs (potential failure points). visual: Swimlane diagram.", tags: ["Strategy, Finance & Operations", "Operations"] },
                    { id: "workflow-automation", title: "Workflow Automation Identifier", content: "Identify candidates for automation. Workflows: [LIST]. Criteria (Score 1-5): **Repetition** - How often? **Volume** - How many? **Rule-based** - No judgement needed? **Error-prone** - Manual errors? **Time-consuming**. High score = Automate. Tools: Zapier, Make, n8n. Example: 'Client signs contract -> Create project in Asana -> Create folder in Drive -> Invoice in Xero -> Slack notification.'", tags: ["Strategy, Finance & Operations", "Operations"] },
                    { id: "quality-control", title: "Quality Control Checklist", content: "Ensure consistent quality of output. Product/Service: [ITEM]. Checklist: **Critical Control Points** - Where can things go wrong? **Standards** - Visual/functional specs. **Inspection** - Steps to verify. **Pass/Fail criteria**. **Correction** - What to do if fail (Rework/Discard). **Recording** - Log results. Frequency: Every batch / Random sampling. Goal: Zero defects.", tags: ["Strategy, Finance & Operations", "Operations"] },
                    { id: "supply-chain", title: "Supply Chain Optimizer", content: "Optimize supply chain efficiency. Product: [PRODUCT]. Components: **Sourcing** - Supplier reliability, cost, backup suppliers. **Manufacturing** - Lead times, MOQ (Minimum Order Quantity), quality. **Logistics** - Shipping costs, speed, customs. **Inventory** - Turnover rate, storage costs. **Risk** - Single points of failure. Strategy: Diversify suppliers, negotiate terms, improve demand forecasting to reduce stockouts/overstock.", tags: ["Strategy, Finance & Operations", "Operations"] },
                    { id: "inventory-management", title: "Inventory Management System", content: "Manage inventory levels effectively. Items: [SKUs]. Metrics: **Reorder Point** - When to order (Lead time demand + Safety stock). **EOQ (Economic Order Quantity)** - Optimal quantity to minimize holding/ordering costs. **First-In-First-Out (FIFO)**. **ABC Analysis** - A items (High value, tight control), B items (Med), C items (Low value, loose control). Tools: Inventory software, barcode system. Goal: Minimize holding cost while maximizing fill rate.", tags: ["Strategy, Finance & Operations", "Operations"] },
                    { id: "vendor-management", title: "Vendor Management Framework", content: "Manage vendor relationships and performance. Vendors: [LIST]. Process: **Selection** - RFP, comparison matrix, reference checks. **Onboarding** - Contracts, payment setup, data access. **Performance** - SLAs (Service Level Agreements), quarterly reviews. **Risk** - Financial stability, security compliance. **Offboarding** - Data retrieval, access revocation. Goal: Strategic partnerships, not just transactional purchasing.", tags: ["Strategy, Finance & Operations", "Operations"] },
                    { id: "project-management-method", title: "Project Management Methodology Selector", content: "Choose right PM methodology for project. Project: [DESCRIBE]. Options: **Waterfall** (Sequential, clear requirements) -> Construction, manufacturing. **Agile/Scrum** (Iterative, changing requirements) -> Software dev. **Kanban** (Continuous flow, visual) -> Support, maintenance. **Critical Path** (Complex dependencies) -> Events, large launches. Recommendation selection based on: Uncertainty level, team size, timeline rigidity, client involvement.", tags: ["Strategy, Finance & Operations", "Operations"] },
                    { id: "kaizen-framework", title: "Continuous Improvement (Kaizen) Framework", content: "Implement culture of continuous improvement. Focus: [AREA]. Cycle (PDCA): **Plan** - Identify problem, root cause (5 Whys), propose solution. **Do** - Implement small pilot test. **Check** - Measure results against baseline. **Act** - Standardize if successful, or iterate. Rituals: Weekly retrospective, suggestion box, Gemba walks (go see the work). Mindset: 1% better every day beats big overhauls.", tags: ["Strategy, Finance & Operations", "Operations"] },
                    { id: "bottleneck-analysis", title: "Bottleneck Identifier & Remover", content: "Identify limits to throughput (Theory of Constraints). Process: [WORKFLOW]. Steps: **1) Identify** - Where does work pile up? Resource always busy? **2) Exploit** - Maximize uptime of bottleneck (no breaks, ensure input always ready). **3) Subordinate** - Pace everything else to the bottleneck. **4) Elevate** - Add capacity to bottleneck (hire, buy tool). **5) Repeat**. Warning: Fixing one bottleneck usually reveals the next one.", tags: ["Strategy, Finance & Operations", "Operations"] }
                ]
            },
            {
                id: "legal-compliance",
                name: "Legal & Compliance",
                icon: "⚖️",
                prompts: [
                    { id: "terms-of-service", title: "Terms of Service Generator", content: "Draft Terms of Service (ToS) outline. Business: [TYPE]. Key clauses: **Acceptance of Terms** - Usage implies agreement. **User Responsibilities** - Account security, prohibited conduct. **Payment Terms** - Billing cycles, refunds, cancellations. **IP Rights** - Who owns content? **Disclaimers** - 'As is' basis, no warranties. **Limitation of Liability** - Cap on damages. **Termination** - Rights to ban users. **Governing Law** - Jurisdiction. **Changes to Terms** - Notification process. Note: Verify with legal counsel.", tags: ["Strategy, Finance & Operations", "Legal & Compliance"] },
                    { id: "privacy-policy", title: "Privacy Policy Builder", content: "Draft Privacy Policy structure (GDPR/CCPA aligned). Operations: [DATA COLLECTED]. Structure: **1) Data Collection** - Types of data (name, email, IP). **2) Usage** - Why collect it? (Service delivery, marketing). **3) Sharing** - Third parties (payment processors, analytics). **4) Storage & Security** - How it's protected. **5) User Rights** - Access, deletion, correction requests. **6) Cookies** - Usage and consent. **7) Contact** - DPO/Privacy email. Statement: Transparency builds trust.", tags: ["Strategy, Finance & Operations", "Legal & Compliance"] },
                    { id: "nda-template", title: "Non-Disclosure Agreement (NDA) Template", content: "Create NDA template. Parties: [Disclosing Party] and [Receiving Party]. Purpose: [Project/Discussion]. Key sections: **Definition of Confidential Information** - What is covered? (Code, trade secrets, data). **Exclusions** - Public knowledge, independent development. **Obligations** - Do not disclose, reasonable protection measures. **Term** - Duration (e.g., 3-5 years). **Permitted Use** - Only for evaluating relationship. **Return of Materials** - Upon termination. **Remedies** - Injunctions for breach.", tags: ["Strategy, Finance & Operations", "Legal & Compliance"] },
                    { id: "contractor-agreement", title: "Contractor Agreement Framework", content: "Structure Independent Contractor Agreement. Role: [ROLE]. Sections: **Scope of Work** - Deliverables, timeline. **Compensation** - Rate, invoicing terms. **Independent Status** - Not an employee, pays own taxes. **IP Ownership** - 'Work for hire' (Company owns IP). **Confidentiality** - NDA clauses. **Termination** - Notice period (e.g., 14 days). **Non-Solicit** - Cannot poach clients/employees. **Dispute Resolution** - Arbitration/Mediation.", tags: ["Strategy, Finance & Operations", "Legal & Compliance"] },
                    { id: "ip-protection", title: "Intellectual Property Protection Guide", content: "Plan IP protection strategy. Assets: [LIST ASSETS]. Strategy: **Trademarks** - Protect brand name, logo, slogan. **Copyright** - Protect creative works, code, content (automatic, but registration helps). **Patents** - Protect novel inventions (expensive, time-consuming). **Trade Secrets** - Protect formulas, algorithms, client lists (via NDAs + Security). **Domains** - Buy defensive domains. **Agreements** - Ensure employee/contractor agreements assign IP to company.", tags: ["Strategy, Finance & Operations", "Legal & Compliance"] },
                    { id: "gdpr-checklist", title: "GDPR Compliance Checklist", content: "Check GDPR compliance status. Checklist: **Lawful Basis** - Consent or legitimate interest for processing. **Consent** - Clear, opt-in (no pre-checked boxes). **Rights** - Can users access, portability, delete data? **Data Minimization** - Collect only what's needed. **Security** - Encryption, access controls. **Breach Notification** - Process to notify within 72h. **DPA** - Data Processing Agreements with vendors. **Record Keeping** - RoPA (Record of Processing Activities).", tags: ["Strategy, Finance & Operations", "Legal & Compliance"] },
                    { id: "data-security-policy", title: "Data Security Policy", content: "Draft internal Data Security Policy. Scope: [COMPANY]. Policies: **Access Control** - MFA enforced, least privilege principle. **Device Security** - Disk encryption, screen locks, antivirus. **Password Policy** - Manager usage, rotation. **Data Handling** - No sensitive data in Slack/Email. **Remote Work** - VPN usage, public Wi-Fi rules. **Incident Response** - Who to contact if breach suspected. **Training** - Annual security awareness training.", tags: ["Strategy, Finance & Operations", "Legal & Compliance"] },
                    { id: "business-license-tracker", title: "Business License & Permit Tracker", content: "Identify and track required licenses. Location: [CITY/STATE]. Business Activity: [TYPE]. Common requirements: **General Business License** - City/County tax certificate. **Professional License** - For regulated industries (Health, Legal, Real Estate). **Sales Tax Permit** - To collect sales tax. **Zoning Permit** - For physical location. **Health Permit** - For food/fitness. **EIN** - Federal tax ID. **Fictitious Business Name (DBA)** - If operating under distinct name. Action: List renewal dates and costs.", tags: ["Strategy, Finance & Operations", "Legal & Compliance"] },
                    { id: "contract-review", title: "Contract Review Checklist", content: "Checklist for reviewing incoming contracts. Contract: [TYPE]. Checks: **Commercial Terms** - Price, payment terms (Net 30/60). **Deliverables** - Clear scope? **Term & Termination** - Auto-renewal? Exit fees? **Liability** - Indemnification clauses (fair?), Limitation of liability caps. **IP** - Who owns new IP created? **Exclusivity** - Are we locked in? **Confidentiality** - Mutual protection? **Governing Law** - Is it our local jurisdiction? Red flag: Unlimited liability.", tags: ["Strategy, Finance & Operations", "Legal & Compliance"] },
                    { id: "compliance-calendar", title: "Compliance Calendar Generator", content: "Create annual compliance calendar. Jurisdiction: [LOCATION]. Events: **Taxes** - Estimated quarterly payments, Annual return, Sales tax filing (monthly/quarterly). **Corporate** - Annual Report/Statement of Information (State), Franchise Tax. **Employment** - W-2/1099 issuance (Jan 31), Workers Comp audit. **Licenses** - Business license renewal. **Insurance** - Policy renewals. **Meetings** - Annual Shareholder Meeting minutes. Purpose: Avoid penalties and bad standing.", tags: ["Strategy, Finance & Operations", "Legal & Compliance"] }
                ]
            },
        ]
    },
    {
        id: "sales-leadership",
        name: "Sales, Leadership & Teams",
        icon: "🤝",
        description: "Sales techniques, customer success, team management, and leadership skills",
        folders: [
            {
                id: "sales-success",
                name: "Sales & Customer Success",
                icon: "📈",
                prompts: [
                    { id: "sales-pitch", title: "Sales Pitch Framework", content: "Craft a persuasive sales pitch. Product: [PRODUCT]. Audience: [BUYER PERSONA]. Framework: **1) The Hook** - surprising stat or keen insight. **2) The Problem** - Agitate the pain they feel. **3) The Solution** - Introduce product as the cure. **4) The Benefits** - WIIFM (What's in it for me?). **5) Social Proof** - Who else uses it? **6) The Ask** - Call to action (Demo? Trial?). Tone: Consultative, not pushy. Focus on value, not features.", tags: ["Sales, Leadership & Teams", "Sales & Success"] },
                    { id: "discovery-call", title: "Discovery Call Script", content: "Script for effective discovery call. Goal: Qualify prospect. Structure: **Rapport** (2 min). **Agenda** (1 min). **Discovery Questions**: 'What prompted you to look for a solution now?', 'How are you currently handling [process]?', 'What's the impact of that problem on revenue/time?', 'Who else is involved in the decision?', 'What is your timeline?'. **Closing**: Summarize pain points, propose next step (Demo), get agreement. Avoid: Pitching too early.", tags: ["Sales, Leadership & Teams", "Sales & Success"] },
                    { id: "objection-handling", title: "Sales Objection Handlers", content: "Handle common sales objections. Objections: **Price** ('Too expensive' -> 'Compared to what? Let's look at ROI.'), **Timing** ('Not now' -> 'What changes in Q3? What is the cost of waiting?'), **Competitor** ('We use X' -> 'X is great for A, but we specialize in B.'). **Authority** ('Need to ask boss' -> 'What will she care about most? Let's equip you.'). Technique: Listen, Validate ('I understand why you say that'), Isolate ('Is price the only blocker?'), Reframe & Resolve.", tags: ["Sales, Leadership & Teams", "Sales & Success"] },
                    { id: "proposal-template", title: "Proposal Template Generator", content: "Create winning proposal structure. Client: [CLIENT]. Structure: **1) Executive Summary** - The 'Why'. **2) Understanding of Requirements** - Prove you listened. **3) Proposed Solution** - Methodology/Deliverables. **4) Investment** - Pricing options (Tiered). **5) Timeline**. **6) Case Studies/Testimonials**. **7) Terms**. **8) Next Steps** - Signature block. Tips: Use their language, focus on outcomes/ROI, keep it visual.", tags: ["Sales, Leadership & Teams", "Sales & Success"] },
                    { id: "crm-strategy", title: "CRM Strategy Builder", content: "Design CRM strategy for team. CRM: [TOOL]. Stages: **Lead** (Unqualified) -> **MQL** (Marketing Qualified) -> **SQL** (Sales Qualified) -> **Opportunity** (Proposal Sent) -> **Negotiation** -> **Closed Won/Lost**. Data Hygiene: Mandatory fields (Source, Industry, Size). Automation: Auto-assign leads, reminder tasks for follow-ups. Analytics: Conversion rates by stage, Lead velocity, Win rate per rep. Goal: Single source of truth.", tags: ["Sales, Leadership & Teams", "Sales & Success"] },
                    { id: "customer-onboarding", title: "Customer Onboarding Checklist", content: "Ensure smooth customer onboarding. Product: [PRODUCT]. Checklist: **1) Welcome Email** - Login details, resources. **2) kickoff Call** - Set goals, meet team. **3) Data Migration/Setup**. **4) Training** - User/Admin training sessions. **5) First Value** - Guide them to 'Aha moment' ASAP. **6) Check-in (Day 30)** - Review usage, address issues. **7) Handoff** - Sales to CS logic. Goal: Drive adoption and Time-to-Value.", tags: ["Sales, Leadership & Teams", "Sales & Success"] },
                    { id: "upsell-cross-sell", title: "Upsell & Cross-sell Strategy", content: "Plan to increase account value. Strategy: **Mapping** - Identify white space in account (unused products/seats). **Trigger events** - New funding, hiring, usage spikes. **Upsell** - 'You're hitting limits, upgrade to Pro for X benefit.' **Cross-sell** - 'You use Product A, adding Product B automates the handoff.' **Timing** - After success milestone (e.g., successful rollout). Approach: 'Help me help you', not 'Give me money'.", tags: ["Sales, Leadership & Teams", "Sales & Success"] },
                    { id: "churn-reduction", title: "Churn Reduction Framework", content: "Reduce customer churn. Analysis: Why are they leaving? (Price, Product gaps, Support, Champion left). **Proactive**: Monitor health scores (usage drops), Quarterly Business Reviews (QBRs) to show value. **Reactive**: Save plays (Discount, Downgrade to pause, Executive reach-out). **Structural**: Annual contracts, sticky features (integrations). Metric: Gross Revenue Churn vs Net Revenue Churn (Goal: Net Negative Churn).", tags: ["Sales, Leadership & Teams", "Sales & Success"] },
                    { id: "customer-success-playbook", title: "Customer Success Playbook", content: "Standardize CS operations. Tiering: **High Touch** (Enterprise) -> Weekly calls, strategic planning. **Low Touch** (Mid-market) -> Monthly check-ins, webinars. **Tech Touch** (SMB) -> Automated emails, help center. Key moments: Onboarding, Renewal (start 90 days out), Risk (ticket spike), Advocacy (ask for referral). Metrics: NDR (Net Dollar Retention), NPS, Time to Resolution.", tags: ["Sales, Leadership & Teams", "Sales & Success"] },
                    { id: "account-management", title: "Account Management Plan", content: "Strategic plan for key account. Client: [CLIENT]. Sections: **Account Overview** - Spend, products, organizational map. **Goals** - What are their yearly objectives? **Health** - Relationships strength, product adoption. **Risks** - Competitors, budget cuts. **Opportunities** - Expansion areas. **Action Plan** - Schedule QBR, executive alignment meeting, training refresher.", tags: ["Sales, Leadership & Teams", "Sales & Success"] },
                    { id: "sales-forecasting", title: "Sales Forecasting Model", content: "Built reliable sales forecast. Methodology: **Stage-Weighted**. Process: **1) Clean Pipeline** - Remove stale deals. **2) Assign Probability** - Discovery (10%), Demo (25%), Proposal (50%), Negotiation (80%), Verbal (95%). **3) Calculate** - Deal Value x Probability = Weighted Forecast. **4) Rollup** - Sum of weighted values vs Quota. **5) Manager Adjustment** - 'Sandbagging' or 'Happy ears'. Frequency: Weekly pipeline review. Accuracy goal: +/- 10%.", tags: ["Sales, Leadership & Teams", "Sales & Success"] },
                    { id: "nps-analyzer", title: "Net Promoter Score (NPS) Analyzer", content: "Analyze and act on NPS feedback. Question: 'How likely to recommend?'. Segments: **Promoters** (9-10), **Passives** (7-8), **Detractors** (0-6). NPS = %Promoters - %Detractors. **Action Loop**: **Promoters** -> Ask for referral/review/case study. **Passives** -> 'What would make it a 10?' (Product feedback). **Detractors** -> Call immediately to resolve issue (Churn risk!). Track trends over time.", tags: ["Sales, Leadership & Teams", "Sales & Success"] }
                ]
            },
            {
                id: "leadership-management",
                name: "Leadership & Team Management",
                icon: "👔",
                prompts: [
                    { id: "one-on-one", title: "One-on-One Meeting Template", content: "Structure effective 1:1 meetings. Frequency: Weekly/Bi-weekly. Agenda: **1) Check-in** - How are you feeling? (Life/Stress). **2) Updates** - Brief blockers/wins (Async is better for status). **3) Priorities** - Alignment for next week. **4) Feedback** - Two-way (Manager to Report, Report to Manager). **5) Career Growth** - Progress on development goals (Monthly). **6) Action Items**. Rule: It's the employee's meeting. Listen 80%, talk 20%.", tags: ["Sales, Leadership & Teams", "Leadership"] },
                    { id: "performance-review", title: "Performance Review Framework", content: "Conduct fair performance review. Period: [Q1/H1]. Structure: **Achievements** - What was delivered? (vs Goals). ** Strengths** - Specific examples of good behaviors. **Areas for Improvement** - Constructive feedback with examples. **Core Values** - Cultural fit. **Goals for Next Period** - 3-5 SMART goals. **Rating** - Calibration. Prep: Gather peer feedback (360), review past 1:1 notes. Tone: Coaching, no surprises (feedback should be continuous).", tags: ["Sales, Leadership & Teams", "Leadership"] },
                    { id: "team-building", title: "Team Building Activities Planner", content: "Plan team building that isn't awkward. Team: [TEAM]. Goal: Trust/Communication/Fun. Ideas: **Remote** - Virtual Escape Room, 'Show & Tell' (desk items), Trivia, Skribbl.io. **In-Person** - Cooking class, volunteering, hiking, hackathon. **Hybrid** - Async photo challenge. **Work-focused** - User Manuals ('How to work with me'), personality tests (Myers-Briggs/Enneagram). Rule: Inclusive (consider time zones, abilities, alcohol preferences).", tags: ["Sales, Leadership & Teams", "Leadership"] },
                    { id: "delegation-matrix", title: "Delegation Decision Matrix", content: "Decide what to delegate. Matrix (Eisenhower/Urgency): **Important & Urgent** -> Do it yourself (or delegate to trusted deputy). **Important & Not Urgent** -> Plan it (Strategic work). **Not Important & Urgent** -> Delegate (Admin, scheduling). **Not Important & Not Urgent** -> Delete. Prioritization: Value/Effort. Delegation Framework: **Task** -> **Who** -> **Why them** -> **Resources** -> **Deadline** -> **Check-in points**. Trust but verify.", tags: ["Sales, Leadership & Teams", "Leadership"] },
                    { id: "conflict-resolution", title: "Conflict Resolution Guide", content: "Resolve team conflict effectively. Situation: [CONFLICT]. Steps: **1) De-escalate** - Separate parties if heated. **2) Listen** - 1:1 with each side. 'Help me understand your perspective'. **3) Identify Root Cause** - Misaligned goals? Role ambiguity? Personality clash? **4) Facilitate Dialogue** - Bring together. Focus on the problem, not the person. Use 'I' statements. **5) Agree on Path Forward** - Actionable steps. **6) Monitor**. Role of Leader: Mediator, not judge.", tags: ["Sales, Leadership & Teams", "Leadership"] },
                    { id: "leadership-development", title: "Leadership Development Plan", content: "Plan for growing as a leader. **Self-Assessment** - Strengths, blind spots (Feedback from team). **Goals** - 'Improve delegation', 'Speak less in meetings', 'Strategic thinking'. **Actions** - Read [Book], Get Mentor, Take Course, Lead [Project]. **Timeline** - Q1/Q2/Q3/Q4. **Metrics** - Team pulse survey scores, promotion of direct reports. Daily habit: Journaling / Reflection.", tags: ["Sales, Leadership & Teams", "Leadership"] },
                    { id: "team-motivation", title: "Team Motivation Strategies", content: "Motivate team beyond money. Drivers (Pink's Drive): **Autonomy** - Give control over how work gets done. **Mastery** - Opportunities to learn and grow. **Purpose** - Connect work to bigger mission/customer impact. Tactics: Public recognition (Kudos), clear career paths, transparent communication, removing blockers, celebratory rituals. Diagnosis: Unmotivated? Check: Burnout? Boredom? Confusion? Lack of psychological safety?", tags: ["Sales, Leadership & Teams", "Leadership"] },
                    { id: "remote-management", title: "Remote Team Management Guide", content: "Manage distributed team effectively. Principles: **Async First** - Write it down (Notion/Google Docs). Minimize meetings. **Output over Hours** - Trust them to work. **Over-communicate** - Context gets lost in text. **Intentional Connection** - Coffee chats, social channels. **Tooling** - Slack, Zoom, Loom, Jira. **Time Zones** - Rotate meeting times. Caution: Watch for isolation and burnout (always on).", tags: ["Sales, Leadership & Teams", "Leadership"] },
                    { id: "hiring-optimizer", title: "Hiring Process Optimizer", content: "Standardize hiring to reduce bias. Role: [ROLE]. Process: **1) Job Description** - Outcome focused, not just requirement list. **2) Sourcing** - Diverse pools. **3) Screening** - Skills assessment (blind if possible). **4) Interviews** - Structured interview guide (same questions for all). **5) Assignment** - Practical work sample. **6) Reference Checks**. **7) Offer**. Scorecard: Rate candidates on weighted criteria, not 'gut feeling'. Speed: Time kills all deals -> Streamline steps.", tags: ["Sales, Leadership & Teams", "Leadership"] },
                    { id: "onboarding-program", title: "Onboarding Program Designer", content: "Design 30-60-90 day onboarding plan. Role: [ROLE]. **Pre-boarding** - Laptop, access, swag, welcome email. **Week 1 (The Sponge)** - Company mission, culture, team intros, tool setup. **Month 1 (Contributor)** - First small project, learn product, shadow calls. **Month 2 (Owner)** - Take ownership of core responsibilities, faster cadence. **Month 3 (Innovator)** - Propose improvements, full autonomy. Goal: Time to productivity.", tags: ["Sales, Leadership & Teams", "Leadership"] },
                    { id: "culture-builder", title: "Company Culture Builder", content: "Define and reinforce company culture. **Values** - 3-5 core principles (e.g., 'Radical Candor', 'Move Fast', 'Customer Obsession'). **Behaviors** - What do those values look like in action? (Rewarding risk-taking vs punishing failure). **Rituals** - All-hands, retreats, demos, hackathons. **Artifacts** - Handbook, swag, office design/remote setup. Culture is what happens when you're not in the room. Hire and fire by values.", tags: ["Sales, Leadership & Teams", "Leadership"] },
                    { id: "change-management", title: "Change Management Framework", content: "Lead team through change (ADKAR). Change: [CHANGE]. **Awareness** - Communicate *why* change is needed. **Desire** - Build support/WIIFM (What's in it for me). **Knowledge** - Teach *how* to change (Training). **Ability** - Provide resources/skills to implement. **Reinforcement** - Sustain change (Rewards, monitoring). Comm plan: Vision -> Plan -> Quick Wins -> Celebration. Expect resistance curve.", tags: ["Sales, Leadership & Teams", "Leadership"] }
                ]
            }
        ]
    }];
